import pytest
from lab2.main_v3 import solve_variant_3

TEST_DATA_V3 = {
    "test_1": {
        "input": """""",
        "output": """946304"""
    },
    "test_2": {
        "input": """""",
        "output": """775232"""
    },
    "test_3": {
        "input": """""",
        "output": """675008"""
    },
    "test_4": {
        "input": """""",
        "output": """91008"""
    },
    "test_5": {
        "input": """""",
        "output": """3904"""
    }
}

@pytest.mark.parametrize("test_name", TEST_DATA_V3.keys())
def test_variant_3_with_manual_data(test_name):
    protein_seq = TEST_DATA_V3[test_name]["input"].strip()
    expected_output_str = TEST_DATA_V3[test_name]["output"].strip()
    
    result = solve_variant_3(protein_seq)
    assert result == int(expected_output_str)
